import json
data = json.load(open('batches/batch_0048.json'))
targets = [2430,2434]
for d in data:
    if d['idx'] in targets:
        for name in ['title','desc','body']:
            b = d[name]
            if not b: continue
            raw = b.encode('latin1', errors='ignore')
            for enc in ['cp932','shift_jis','euc_jp']:
                try:
                    fixed = raw.decode(enc)
                    print(d['idx'], name, enc, "->", fixed[:200])
                except Exception as e:
                    pass
        print('---')
EOF
